const NUMERIC_FIELDS = [
  'Calories', 'Proteins', 'Carbs', 'Fats',
  'Магний', 'Витамин D', 'Омега-3 (EPA/DHA)', 'Селен', 'Йод',
  'Калий', 'Железо', 'Кальций', 'Витамин B12', 'Витамин К',
  'Витамин Е', 'Цинк',
  'Клетчатка', 'Холестерин',
  'Добавленный сахар',
  'Натрий',
  'Кофеин',
  'Алкоголь',
  'Насыщенные жиры',
  'Трансжиры',
  'Вода',
];

// ------------------------------------------------------------
// Вспомогательные функции
// ------------------------------------------------------------

/**
 * Безопасное преобразование строки в число
 */
function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;
  const num = parseFloat(value);
  return isNaN(num) ? 0 : num;
}

/**
 * Парсинг даты с учётом временной зоны и сдвига ±2 часа
 * Если время < 2:00, считаем предыдущим днём
 */
function parseDateWithShift(dateStr) {
  if (!dateStr) return null;

  let date;
  if (dateStr instanceof Date) {
    date = new Date(dateStr);
  } else {
    const str = String(dateStr).trim();
    const isoMatch = str.match(/^(\d{4}-\d{2}-\d{2})[T ]/);
    if (isoMatch) {
      date = new Date(str);
    } else {
      const ymdMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (ymdMatch) {
        date = new Date(parseInt(ymdMatch[1]), parseInt(ymdMatch[2]) - 1, parseInt(ymdMatch[3]), 12, 0, 0);
      } else {
        const dmyMatch = str.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
        if (dmyMatch) {
          date = new Date(parseInt(dmyMatch[3]), parseInt(dmyMatch[2]) - 1, parseInt(dmyMatch[1]), 12, 0, 0);
        } else {
          date = new Date(str);
        }
      }
    }
  }

  if (isNaN(date.getTime())) return null;

  const hours = date.getHours();
  if (hours < 2) {
    date.setDate(date.getDate() - 1);
  }
  return date;
}

/**
 * Форматирование даты в YYYY-MM-DD
 */
function formatDate(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Получить самую позднюю дату (без учёта сдвига, для определения окна)
 */
function getMaxDate(rows) {
  let maxDate = null;
  rows.forEach(row => {
    const date = parseDateWithShift(row.Date);
    if (date && (!maxDate || date > maxDate)) {
      maxDate = date;
    }
  });
  return maxDate;
}

/**
 * Проверить, попадает ли дата в окно последних N дней (не включая maxDate)
 */
function isWithinLastNDays(date, maxDate, nDays) {
  if (!date || !maxDate) return false;
  if (date >= maxDate) return false;
  const diffTime = maxDate - date;
  const diffDays = diffTime / (1000 * 60 * 60 * 24);
  return diffDays > 0 && diffDays <= nDays;
}

/**
 * Расчёт коэффициента вариации (в процентах)
 */
function calcVariation(values) {
  if (values.length < 2) return null;
  const mean = values.reduce((sum, v) => sum + v, 0) / values.length;
  const squaredDiffs = values.map(v => Math.pow(v - mean, 2));
  const variance = squaredDiffs.reduce((sum, v) => sum + v, 0) / values.length;
  const stdDev = Math.sqrt(variance);
  return (stdDev / mean) * 100;
}

