// === ОБРАБОТКА ЧИСЛОВЫХ ДАННЫХ ===
for (const [key, value] of Object.entries(summary)) {
  if (key.startsWith('sum_')) {
    const cleanKey = key.replace('sum_', '');
    if (typeof value === 'number') {
      result[cleanKey] = Math.round(value / days); 
    }
  }
}
result.daysTracked = days;

// === ФОРМИРУЕМ СПИСКИ ПО ПРИЕМАМ ПИЩИ ===
function formatMeals(arr) {
  if (!arr || !Array.isArray(arr)) return "Нет данных";
  const valid = arr.filter(m => m && String(m).trim() !== '');
  if (valid.length > 0) return "- " + valid.join('\n- ');
  return "Нет данных";
}

result.Breakfast_Meals = formatMeals(summary.appended_meal_breakfast);
result.Lunch_Meals = formatMeals(summary.appended_meal_lunch);
result.Snack_Meals = formatMeals(summary.appended_meal_snack);
result.Dinner_Meals = formatMeals(summary.appended_meal_dinner);

// === ОПРЕДЕЛЕНИЕ СЕЗОНА ===
const vlNow = new Date(Date.now() + 10 * 3600000);
const month = vlNow.getUTCMonth(); 
const seasons = ['зима', 'зима', 'весна', 'весна', 'весна', 'лето', 'лето', 'лето', 'осень', 'осень', 'осень', 'зима'];
result.season = seasons[month];
result.month = month + 1;

return [{ json: result }];
